// Adapted from mastermorphic morphic/lib/tools/search.ts:20-167 @ c9b8310: the `ai` tool() wrapper is a
// plain object; the model-specific schema, the provider selection and the searxng / Brave branches are
// replaced by one injected provider (the shape createSearchProvider returns, search.ts:111). The error
// handling and the citation mapping are verbatim.
export function createSearchTool(searchProvider) {
  return {
    async *execute(
      {
        query,
        max_results = 20,
        search_depth = 'basic', // Default for standard schema
        include_domains = [],
        exclude_domains = []
      },
      context
    ) {
      // Yield initial searching state
      yield {
        state: 'searching',
        query
      }
      // Ensure max_results is at least 10
      const minResults = 10
      const effectiveMaxResults = Math.max(
        max_results || minResults,
        minResults
      )
      let searchResult

      try {
        searchResult = await searchProvider.search(
          query,
          effectiveMaxResults,
          search_depth,
          include_domains,
          exclude_domains
        )
      } catch (error) {
        console.error('Search API error:', error)
        // Re-throw the error to let AI SDK handle it properly
        throw error instanceof Error ? error : new Error('Unknown search error')
      }

      // Add citation mapping and toolCallId to search results
      if (searchResult.results && searchResult.results.length > 0) {
        const citationMap = {}
        searchResult.results.forEach((result, index) => {
          citationMap[index + 1] = result // Citation numbers start at 1
        })
        searchResult.citationMap = citationMap
      }

      // Add toolCallId from context
      if (context?.toolCallId) {
        searchResult.toolCallId = context.toolCallId
      }

      // Yield final results with complete state
      yield {
        state: 'complete',
        ...searchResult
      }
    }
  }
}

// Adapted from mastermorphic morphic/lib/tools/todo.ts:29-59 @ c9b8310: the `ai` tool() wrapper is a
// plain object and the zod input schema (todo.ts:4-27) is left out. That schema gives every todo a
// priority (enum, default 'medium') and describes `todos` as "The complete list of todos". The execute
// body is verbatim.
export function createTodoTools() {
  // Session-scoped todos storage - isolated per tool instance
  let sessionTodos = []
  const todoWrite = {
    description:
      'Create or update todos to track progress on complex tasks. Use this to maintain a list of action items. The response includes completedCount and totalCount to verify task completion.',
    execute: async ({ todos, progressMessage }) => {
      // Update session todos - ensure priority is always set
      sessionTodos = todos.map(todo => ({
        ...todo,
        priority: todo.priority || 'medium'
      }))

      // Calculate progress
      const completedCount = todos.filter(t => t.status === 'completed').length
      const totalCount = todos.length

      return {
        success: true,
        message: progressMessage || `Updated ${totalCount} todos`,
        completedCount,
        totalCount,
        todos: sessionTodos
      }
    }
  }

  return { todoWrite }
}

